import{_ as t,o as r,c as i,a2 as n}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Wie installiere ich den Adapter und was tue ich, wenn die Instanz nicht startet?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/02.installation.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/installation.md","filePath":"de/adapter/esphome/erste-schritte/installation.md","lastUpdated":1795571670000}'),a={name:"de/adapter/esphome/erste-schritte/installation.md"};function s(o,e,d,l,h,c){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="wie-installiere-ich-den-adapter-und-was-tue-ich-wenn-die-instanz-nicht-startet" tabindex="-1">Wie installiere ich den Adapter und was tue ich, wenn die Instanz nicht startet? <a class="header-anchor" href="#wie-installiere-ich-den-adapter-und-was-tue-ich-wenn-die-instanz-nicht-startet" aria-label="Permalink to &quot;Wie installiere ich den Adapter und was tue ich, wenn die Instanz nicht startet?&quot;">​</a></h1><p><a id="install-older-version-pre-release"></a></p><h2 id="wie-installiere-ich-eine-altere-version-oder-eine-vorabversion" tabindex="-1">Wie installiere ich eine ältere Version oder eine Vorabversion? <a class="header-anchor" href="#wie-installiere-ich-eine-altere-version-oder-eine-vorabversion" aria-label="Permalink to &quot;Wie installiere ich eine ältere Version oder eine Vorabversion?&quot;">​</a></h2><p>Vorabversionen und ältere Versionen installierst du in der Konsole des ioBroker-Rechners. Das ioBroker-Repository bietet Vorabversionen nicht an.</p><table tabindex="0"><thead><tr><th>Ziel</th><th>Befehl</th></tr></thead><tbody><tr><td>aktuelle Vorabversion</td><td><code>iobroker url iobroker.esphome@next</code></td></tr><tr><td>bestimmte Version</td><td><code>iobroker url iobroker.esphome@2.0.0-beta.2</code></td></tr><tr><td>zurück zur freigegebenen Version</td><td><code>iobroker url iobroker.esphome</code></td></tr></tbody></table><p>Alle Versionen mit ihren Änderungen stehen unter <a href="https://github.com/DrozmotiX/ioBroker.esphome/releases" target="_blank" rel="noreferrer">Releases</a>. Die Instanz und ihre Einstellungen bleiben beim Wechsel erhalten. Installierst du den Adapter zum ersten Mal auf diesem Weg, legt ioBroker keine Instanz an. Leg sie dann im Admin im Tab „Adapter“ selbst an.</p><p><a id="instance-stay-red-after-install"></a></p><h2 id="warum-bleibt-die-instanz-nach-installation-oder-update-rot" tabindex="-1">Warum bleibt die Instanz nach Installation oder Update rot? <a class="header-anchor" href="#warum-bleibt-die-instanz-nach-installation-oder-update-rot" aria-label="Permalink to &quot;Warum bleibt die Instanz nach Installation oder Update rot?&quot;">​</a></h2><p>Die Instanz ist grün, solange der Adapter läuft. Das steht in <code>esphome.0.info.connection</code>. Ob Geräte verbunden sind, ändert daran nichts. Die verbundenen Geräte stehen in <code>esphome.0.info.connectedDevices</code>.</p><p>Bleibt die Instanz rot, läuft der Adapter nicht. Den Grund findest du im Log der Instanz:</p><ol><li>Öffne im Admin den Tab „Log“ und filtere auf <code>esphome.0</code>.</li><li>Steht dort ein Hinweis auf die Node.js-Version, installiere Node.js 22.12 oder neuer.</li><li>Steht dort ein Fehler beim Laden des Adapters, installiere ihn neu, z. B. mit <code>iobroker url iobroker.esphome</code>, und starte die Instanz.</li></ol><p>Ein Dashboard, das nicht startet, macht die Instanz nicht rot. Dann stehen der Fehler im Log und der Grund im Reiter „ESPHome-Dashboard“.</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Warum startet das Dashboard nicht?</a></p><p><a id="adapter-not-installed-compiled-after"></a></p><h2 id="warum-lasst-sich-der-adapter-nach-einer-backup-wiederherstellung-nicht-installieren-oder-kompilieren" tabindex="-1">Warum lässt sich der Adapter nach einer Backup-Wiederherstellung nicht installieren oder kompilieren? <a class="header-anchor" href="#warum-lasst-sich-der-adapter-nach-einer-backup-wiederherstellung-nicht-installieren-oder-kompilieren" aria-label="Permalink to &quot;Warum lässt sich der Adapter nach einer Backup-Wiederherstellung nicht installieren oder kompilieren?&quot;">​</a></h2><p>Eine Wiederherstellung bringt die Einstellungen und Datenpunkte zurück. Den Adapter installiert ioBroker dabei neu, eventuell in einer älteren Version. Die Python-Umgebung des Dashboards liegt außerhalb von ioBroker und gehört nicht zur Sicherung.</p><p>So bringst du alles wieder zum Laufen:</p><ol><li>Prüfe im Admin im Tab „Adapter“ die installierte Version. Ist sie alt, installiere die aktuelle, z. B. mit <code>iobroker url iobroker.esphome</code>.</li><li>Startet das Dashboard nicht, drück im Reiter „ESPHome-Dashboard“ auf „Python-Umgebung zurücksetzen“ und starte die Instanz neu. Der Adapter baut die Umgebung beim Start neu auf.</li><li>Prüfe im Reiter „Geräte“, ob alle Geräte verbunden sind.</li></ol><p><strong>Siehe auch:</strong> <a href="./../anleitungen/yaml-dateien#back-up-restore-esphome-files">ESPHome-Dateien sichern und wiederherstellen</a> · <a href="./../fehlerbehebung/dashboard-startet-nicht#clear-autopy-cache-if-python">Python-Umgebung zurücksetzen</a></p>',19)])])}const b=t(a,[["render",s]]);export{p as __pageData,b as default};
